/**
 * A user of an app, as returned by `App.users()` and `App.getUsers()`.
 */
export type AppUser = {
    /**
     * The user's username.
     */
    username: string;
    /**
     * The user's unique identifier.
     */
    user_uuid: string;
    /**
     * The user's email address. Only present when the user granted
     * this app the `user:<uuid>:email:read` permission (e.g. via `puter.perms.requestEmail()`); omitted
     * otherwise. May be `null` if the user granted access but has no email on file.
     */
    user_email?: string | null | undefined;
};
/**
 * Pagination options for `App.getUsers()`.
 */
export type GetUsersOptions = {
    /**
     * The number of users to retrieve. Default is `100`.
     */
    limit?: number | undefined;
    /**
     * The offset to start retrieving users from. Default is `0`.
     */
    offset?: number | undefined;
};
/**
 * The `App` object containing Puter app details.
 */
export type App = {
    /**
     * The unique identifier of the app, generated by Puter when the app is created.
     */
    uid: string;
    /**
     * The name of the app.
     */
    name: string;
    /**
     * The URL of the index file of the app, loaded when the app is started.
     */
    index_url: string;
    /**
     * The title of the app.
     */
    title?: string | undefined;
    /**
     * The description of the app.
     */
    description?: string | undefined;
    /**
     * The Data URL of the icon of the app (a base64 encoded image).
     */
    icon?: string | undefined;
    /**
     * Whether the app should be maximized when it is started.
     * Default is `false`.
     */
    maximize_on_start?: boolean | undefined;
    /**
     * Whether the app should run in the background. Default is `false`.
     */
    background?: boolean | undefined;
    /**
     * The file types that the app can open. Each string is in
     * the format `".<extension>"` or `"mime/type"`, e.g. `[".txt", "image/png"]`. For a directory
     * association, the string should be `.directory`.
     */
    filetype_associations?: string[] | undefined;
    /**
     * Custom metadata for the app as arbitrary key-value pairs.
     */
    metadata?: Record<string, unknown> | undefined;
    /**
     * The date and time when the app was created, in `YYYY-MM-DDTHH:MM:SSZ`
     * format.
     */
    created_at?: string | undefined;
    /**
     * The number of times the app has been opened. If `stats_period` is set
     * to a value other than `all`, this is the count within that period.
     */
    open_count?: number | undefined;
    /**
     * The number of users that have access to the app. If `stats_period` is
     * set to a value other than `all`, this is the count within that period.
     */
    user_count?: number | undefined;
    /**
     * Iterates over all users of the
     * app, fetching them page by page. `pageSize` defaults to 100.
     */
    users: (pageSize?: number) => AsyncIterableIterator<AppUser>;
    /**
     * Retrieves a list of users one
     * page at a time as defined by limit and offset.
     */
    getUsers: (params?: GetUsersOptions) => Promise<AppUser[]>;
};
/**
 * The result returned by `Apps.create()`.
 */
export type CreateAppResult = {
    /**
     * The unique identifier of the app, generated by Puter when the app is created.
     */
    uid: string;
    /**
     * The name of the app.
     */
    name: string;
    /**
     * The title of the app.
     */
    title: string;
    /**
     * The URL of the index file of the app, loaded when the app is started.
     */
    index_url: string;
    /**
     * The subdomain assigned to the app.
     */
    subdomain: string;
    /**
     * Information about the owner of the app.
     */
    owner: {
        username: string;
        uuid: string;
    };
};
/**
 * Options for `Apps.list()` and `Apps.get()`.
 */
export type AppListOptions = {
    /**
     * The period for which to get the user and open count. One of
     * `today`, `yesterday`, `7d`, `30d`, `this_month`, `last_month`, `this_year`, `last_year`,
     * `month_to_date`, `year_to_date`, or `last_12_months`. Default is `all` (all time).
     */
    stats_period?: string | undefined;
    /**
     * The size of the icons to return.
     * Default is `null` (the original size).
     */
    icon_size?: 16 | 32 | 64 | 128 | 256 | 512 | null | undefined;
};
/**
 * Options for creating an app with `Apps.create()`.
 */
export type CreateAppOptions = {
    /**
     * The name of the app to create. Must be unique to the user's apps; if an app
     * with this name already exists the promise is rejected.
     */
    name: string;
    /**
     * The URL of the app's index page, displayed when the app is started. Must
     * start with `http://` or `https://`; other protocols are not allowed.
     */
    indexURL: string;
    /**
     * The human-readable title of the app. Defaults to `name` if not provided.
     */
    title?: string | undefined;
    /**
     * The description of the app aimed at the end user.
     */
    description?: string | undefined;
    /**
     * The icon of the app.
     */
    icon?: string | undefined;
    /**
     * Whether the app should be maximized when it is started.
     * Defaults to `false`.
     */
    maximizeOnStart?: boolean | undefined;
    /**
     * Whether the app should run in the background. Defaults to `false`.
     */
    background?: boolean | undefined;
    /**
     * The filetypes that the app can open. File extensions and
     * MIME types are supported, e.g. `[".txt", ".md", "application/pdf"]`. Defaults to `[]`.
     */
    filetypeAssociations?: string[] | undefined;
    /**
     * Custom metadata for the app as arbitrary key-value pairs.
     */
    metadata?: Record<string, unknown> | undefined;
    /**
     * Whether to deduplicate the app name if it already exists. Defaults to
     * `false`.
     */
    dedupeName?: boolean | undefined;
};
/**
 * Attributes to update with `Apps.update()`.
 */
export type UpdateAppAttributes = {
    /**
     * The new name of the app. Must be unique to the user's apps; if an app with
     * this name already exists the promise is rejected.
     */
    name?: string | undefined;
    /**
     * The new URL of the app's index page. Must be accessible to the user.
     */
    indexURL?: string | undefined;
    /**
     * The new title of the app.
     */
    title?: string | undefined;
    /**
     * The new description of the app aimed at the end user.
     */
    description?: string | undefined;
    /**
     * The new icon of the app.
     */
    icon?: string | undefined;
    /**
     * Whether the app should be maximized when it is started.
     * Defaults to `false`.
     */
    maximizeOnStart?: boolean | undefined;
    /**
     * Whether the app should run in the background. Defaults to `false`.
     */
    background?: boolean | undefined;
    /**
     * The filetypes that the app can open. File extensions and
     * MIME types are supported, e.g. `[".txt", ".md", "application/pdf"]`. Defaults to `[]`.
     */
    filetypeAssociations?: string[] | undefined;
    /**
     * Custom metadata for the app as arbitrary key-value pairs.
     */
    metadata?: Record<string, unknown> | undefined;
};
/**
 * The result returned by `Apps.checkName()`.
 */
export type CheckAppNameResult = {
    /**
     * The name that was checked.
     */
    name: string;
    /**
     * Whether the name is available.
     */
    available: boolean;
};
